#!/usr/bin/env bash
# Created by Lokinya (lokinyauv-create). Generated by AI (Claude, Anthropic). Apache-2.0.
# Makes the spoken hints (voice/*.ogg) with Microsoft Edge TTS, female Ukrainian voice. Needs `edge-tts` and `ffmpeg`.
# usage: make_voice.sh [EDGE_TTS_BINARY]
set -euo pipefail
cd "$(dirname "$0")"
EDGE="${1:-edge-tts}"
VOICE="uk-UA-PolinaNeural"
say() {  # id text
  [[ -s "$1.ogg" ]] && return 0
  "$EDGE" --voice "$VOICE" --rate=+0% --text "$2" --write-media "$1.mp3" 2>/dev/null
  ffmpeg -y -loglevel error -i "$1.mp3" -c:a libvorbis -q:a 4 "$1.ogg"
  rm -f "$1.mp3"
}
say few_trackers    "Не бачу всі три трекери. Перевір, що вони увімкнені."
say need_stand      "Не вдалося визначити зріст. Стань рівно, і відкалібруйся у ВіЕрЧат ще раз."
echo done
